import {
  SortableRoot,
  SortableItem,
  useSortableList,
} from "@/components/bevelui/sortable";

type Task = { id: string; title: string; status: string };

export function TaskList() {
  const { items, setItems } = useSortableList<Task>([
    { id: "1", title: "Review PR #42", status: "In progress" },
    { id: "2", title: "Update changelog", status: "Todo" },
    { id: "3", title: "Deploy to staging", status: "Todo" },
  ]);

  return (
    <SortableRoot items={items} onReorder={setItems}>
      {items.map((task) => (
        <SortableItem
          key={task.id}
          id={task.id}
          className="flex items-center justify-between px-4 py-3 mb-1 rounded-lg border border-border bg-card cursor-grab"
        >
          <span className="text-sm">{task.title}</span>
          <span className="text-xs text-muted-foreground">{task.status}</span>
        </SortableItem>
      ))}
    </SortableRoot>
  );
}

import {
  SortableRoot,
  SortableItem,
  SortableHandle,
  useSortableList,
} from "@/components/bevelui/sortable";

<SortableRoot items={items} onReorder={setItems}>
  {items.map((task) => (
    <SortableItem
      key={task.id}
      id={task.id}
      handle
      className="flex items-center gap-3 px-3 py-3 mb-1 rounded-lg border border-border bg-card"
    >
      <SortableHandle />
      <span className="text-sm flex-1">{task.title}</span>
      <button onClick={() => remove(task.id)} className="text-xs text-muted-foreground">
        Remove
      </button>
    </SortableItem>
  ))}
</SortableRoot>

import { useSortableList } from "@/components/bevelui/sortable";

const { items, setItems, insert, remove, update, move } = useSortableList([
  { id: "1", title: "First task", priority: "high" },
  { id: "2", title: "Second task", priority: "low" },
]);

// Append to end
insert({ id: crypto.randomUUID(), title: "New task", priority: "low" });

// Insert at index 0
insert({ id: crypto.randomUUID(), title: "Urgent", priority: "high" }, 0);

// Remove by id
remove("2");

// Patch a field without touching id
update("1", { priority: "low" });

// Keyboard-style navigation
move("1", "up");   // shift one position up
move("1", "down"); // shift one position down — no-op at boundary
